def render(slug, d):
    goals=''.join(f'<li>{x}</li>' for x in d['goals']); core=''.join(f'<p>{x}</p>' for x in d['core'])
    notes=''.join(f'<li>{x}</li>' for x in d['notes']); summary=''.join(f'<li>{x}</li>' for x in d['summary'])
    quiz=''.join(f'<p class="quiz-q">{i}. {q}</p><p class="quiz-a"><strong>해설</strong> — {a}</p>' for i,(q,a) in enumerate(d['quiz'],1))
    refs=re.sub(r'(https://[^ <]+)', r'<a href="\1">\1</a>', d['refs'])
    return f'''<!--meta: {d['hours']} | 코드 Jupyter Notebook | 장르 산문 -->
<h2 id="b1"><span class="no">1</span>학습 목표</h2><div class="goal"><ul>{goals}</ul></div>
<h2 id="b2"><span class="no">2</span>이 내용을 배우는 이유</h2><p>{d['reason']}</p>
<h2 id="b3"><span class="no">3</span>앞에서 배운 내용</h2><p>{d['prior']}</p>
<h2 id="b4"><span class="no">4</span>핵심 개념</h2><h3>정의와 관찰</h3>{core}
<figure>{{{{svg:{slug.split('-')[0]}-concept}}}}<figcaption>파란색은 학습자가 따라갈 입력 흐름, 녹색은 도구와 자료, 보라색은 모델의 처리, 노란색은 측정 결과, 빨간은 확인할 제한을 뜻합니다. 화살표를 왼쪽에서 오른쪽으로 읽습니다.</figcaption></figure>
<h2 id="b5"><span class="no">5</span>실행 예제</h2><p>노트북을 새 Python 3.12 커널에서 첫 셀부터 순서대로 실행합니다. 코드 셀 앞의 설명에서 고정한 값과 바꾼 값을 확인한 뒤 출력 원문을 읽습니다.</p>{{{{notebook:{slug}}}}}<p class="look"><b>확인할 점</b> — 출력에서 수치와 문자열을 먼저 확인하고, 본문의 해석이 관찰한 범위를 넘지 않는지 대조합니다.</p>
<h2 id="b6"><span class="no">6</span>실험 결과 해석</h2><p>{d['interpret']}</p>
<h2 id="b7"><span class="no">7</span>주의할 점과 실무 메모</h2><ul>{notes}</ul>
<h2 id="b8"><span class="no">8</span>정리와 다음 절</h2><ul>{summary}</ul><p><strong>다음 학습과 이어지는 지점</strong> — {d['next']}</p>
<h2 id="b9"><span class="no">9</span>복습 문제</h2><details class="quiz"><summary>문제와 해설</summary>{quiz}</details>
<h2 id="b10"><span class="no">10</span>참고 자료</h2><ul>{refs}</ul>'''

for slug,d in lessons.items():
    (HERE/'_src'/f'{slug}.html').write_text(render(slug,d),encoding='utf-8')
    print('wrote',slug)
